#!/usr/bin/env python3
"""Generates src/encoding/codepagetables.cpp: the high half (#80-#FF) of every single-byte code page as Unicode code
points, from Python's codec tables (the reference). A byte a code page leaves undefined maps to U+F700 + byte, so
it round-trips. Run from the library root: python3 tools/scripts/gen-codepage-tables.py"""

PAGES = [("Cp866", "cp866"), ("Koi8r", "koi8_r"), ("Cp1251", "cp1251")]


def high_half(codec):
    out = []
    for b in range(0x80, 0x100):
        try:
            ch = bytes([b]).decode(codec)
            out.append(ord(ch))
        except UnicodeDecodeError:
            out.append(0xF700 + b)
    return out


# The ZX Spectrum's #80-#8F block graphics: bit 0 top right, bit 1 top left, bit 2 bottom right, bit 3 bottom left;
# #80 (no quadrant) is U+00A0 so it does not collide with the space at #20
QUADRANTS = {0: 0x00A0, 1: 0x259D, 2: 0x2598, 3: 0x2580, 4: 0x2597, 5: 0x2590, 6: 0x259A, 7: 0x259C,
             8: 0x2596, 9: 0x259E, 10: 0x258C, 11: 0x259B, 12: 0x2584, 13: 0x259F, 14: 0x2599, 15: 0x2588}


def zx_high_half():
    return [QUADRANTS[b - 0x80] if b < 0x90 else 0xF700 + b for b in range(0x80, 0x100)]


def table(name, points):
    lines = [f"const char32_t k{name}High[128] = {{"]
    for i in range(0, 128, 8):
        row = ", ".join(f"0x{p:04X}" for p in points[i:i + 8])
        lines.append(f"    {row},  // #{0x80 + i:02X}")
    lines.append("};")
    return "\n".join(lines)


parts = [table(n, high_half(c)) for n, c in PAGES] + [table("ZxSpectrum", zx_high_half())]
src = """// Generated by tools/scripts/gen-codepage-tables.py from Python's codec tables - do not edit by hand.
// The high half (#80-#FF) of every single-byte code page as Unicode code points; U+F700 + byte = undefined byte.

#include "encoding/codepagetables.h"

namespace unrealasm::encoding::tables
{
""" + "\n\n".join(parts) + """
}  // namespace unrealasm::encoding::tables
"""
open("src/encoding/codepagetables.cpp", "w").write(src)
print("written src/encoding/codepagetables.cpp")
